package settingsfile

// help is what the page says about a setting, in English and German, from the server (the pages stay small). Each entry says what
// the setting does and, where it matters, what the default is or what it changes only with the next viper up. A test asks for
// both languages for everything the catalog offers.
func helpTexts() map[string][2]string {
	return map[string][2]string{
		"PROVIDER":                        {"Where the machines run: hetzner, aws, gcp, azure, kubernetes or compose. Default: hetzner. Only the settings files say it, not the shell.", "Wo die Rechner laufen: hetzner, aws, gcp, azure, kubernetes oder compose. Standard: hetzner. Nur die Einstellungsdateien sagen es, nicht die Shell."},
		"DNS_PROVIDER":                    {"Who makes the DNS name: cloudflare (needs DNS_DOMAIN and a token) or none (no record, no domain). Default: cloudflare. Containers need none.", "Wer den DNS-Namen anlegt: cloudflare (braucht DNS_DOMAIN und ein Token) oder none (kein Eintrag, keine Domain). Standard: cloudflare. Container brauchen none."},
		"DNS_DOMAIN":                      {"Your domain for the DNS names; required with cloudflare.", "Ihre Domain für die DNS-Namen; Pflicht mit cloudflare."},
		"SERVER_PREFIX":                   {"The beginning of the names of everything viper makes (claude-web). Default: claude. Not changed while a machine has a server: viper down looks for it by this name.", "Der Anfang der Namen von allem, was viper anlegt (claude-web). Standard: claude. Wird nicht geändert, solange ein Rechner einen Server hat: viper down sucht ihn unter diesem Namen."},
		"SERVER_TYPE":                     {"Size of the machine: the type at Hetzner, AWS, GCP and Azure; <CPUs>x<GiB> (2x4) for kubernetes and compose. Applies from the next viper up of a new server.", "Größe des Rechners: der Typ bei Hetzner, AWS, GCP und Azure; <CPUs>x<GiB> (2x4) bei kubernetes und compose. Gilt ab dem nächsten viper up eines neuen Servers."},
		"SERVER_LOCATION":                 {"Where the machine runs: a location, region or zone; with kubernetes the context of the kubeconfig, with compose the Docker context (default is the local daemon). Not changed while a machine has a server.", "Wo der Rechner läuft: Standort, Region oder Zone; bei kubernetes der Kontext der kubeconfig, bei compose der Docker-Kontext (default ist der lokale Daemon). Wird nicht geändert, solange ein Rechner einen Server hat."},
		"SERVER_IMAGE":                    {"Operating system image (AWS, GCP, Azure, Hetzner). Not used by kubernetes and compose: they take K8S_IMAGE and COMPOSE_IMAGE.", "Betriebssystem-Image (AWS, GCP, Azure, Hetzner). Bei kubernetes und compose ungenutzt: dort gelten K8S_IMAGE und COMPOSE_IMAGE."},
		"COMPOSE_IMAGE":                   {"Image of the machines for compose; viper image build makes it. Default: the published image of this version of viper.", "Image der Rechner für compose; viper image build baut es. Standard: das veröffentlichte Image dieser Version von viper."},
		"K8S_IMAGE":                       {"Image of the machines for kubernetes; viper image build makes it. Default: the published image of this version of viper.", "Image der Rechner für kubernetes; viper image build baut es. Standard: das veröffentlichte Image dieser Version von viper."},
		"K8S_DOCKER":                      {"Docker on the machine (kubernetes): dind (a privileged sidecar), remote (a daemon at K8S_DOCKER_HOST) or none. Default: dind. Dangerous values ask for the name of the machine.", "Docker auf dem Rechner (kubernetes): dind (ein privilegierter Sidecar), remote (ein Daemon unter K8S_DOCKER_HOST) oder none. Standard: dind. Gefährliche Werte verlangen den Namen des Rechners."},
		"COMPOSE_DOCKER":                  {"Docker on the machine (compose): dind (a privileged second container), remote (a daemon at COMPOSE_DOCKER_HOST) or none. Default: dind. Dangerous values ask for the name of the machine.", "Docker auf dem Rechner (compose): dind (ein privilegierter zweiter Container), remote (ein Daemon unter COMPOSE_DOCKER_HOST) oder none. Standard: dind. Gefährliche Werte verlangen den Namen des Rechners."},
		"WORKSPACE_DIR":                   {"Directory on the server where repositories are cloned. Containers only below /home/builder/. Default: /home/builder/work.", "Verzeichnis auf dem Server, in das Repositories geklont werden. Bei Containern nur unter /home/builder/. Standard: /home/builder/work."},
		"REPO_URL":                        {"Repository that viper up clones at the start. No credentials in the URL: use VIPER_GH_TOKEN or GIT_DEPLOY_KEY_FILE.", "Repository, das viper up beim Start klont. Keine Zugangsdaten in der URL: nehmen Sie VIPER_GH_TOKEN oder GIT_DEPLOY_KEY_FILE."},
		"REPO_BRANCH":                     {"Branch to clone. Default: the default branch of the repository.", "Zweig, der geklont wird. Standard: der Standardzweig des Repositorys."},
		"SSH_ALLOWED_CIDRS":               {"Networks that may reach SSH (port 22), separated by commas. Default: 0.0.0.0/0,::/0 (everyone). Narrow it to your networks; it does not apply to pods and containers.", "Netze, die SSH (Port 22) erreichen dürfen, durch Komma getrennt. Standard: 0.0.0.0/0,::/0 (alle). Beschränken Sie es auf Ihre Netze; es gilt nicht für Pods und Container."},
		"GROUP_MACHINES":                  {"Only in a group file: the machines of the group, separated by commas. A machine may be named in one group only. Not changed while a machine of the group has a server.", "Nur in einer Gruppendatei: die Rechner der Gruppe, durch Komma getrennt. Ein Rechner darf nur in einer Gruppe stehen. Wird nicht geändert, solange ein Rechner der Gruppe einen Server hat."},
		"NATS_ENABLED":                    {"true: the machine belongs to a NATS group (Hetzner only). Needs NATS_GROUP.", "true: der Rechner gehört zu einer NATS-Gruppe (nur Hetzner). Braucht NATS_GROUP."},
		"NATS_GROUP":                      {"Name of the NATS group: 1 to 31 lowercase letters, digits and hyphens; in a group file the name of the file.", "Name der NATS-Gruppe: 1 bis 31 Kleinbuchstaben, Ziffern und Bindestriche; in einer Gruppendatei der Name der Datei."},
		"NATS_PORT":                       {"Port of the NATS server in the private network (1024 to 65535). Default: 4222.", "Port des NATS-Servers im privaten Netzwerk (1024 bis 65535). Standard: 4222."},
		"NATS_MCP":                        {"true: viper up installs the MCP server viper-nats-mcp and registers it with Claude Code on the machine. Needs NATS_ENABLED.", "true: viper up installiert den MCP-Server viper-nats-mcp und trägt ihn bei Claude Code auf dem Rechner ein. Braucht NATS_ENABLED."},
		"NATS_MCP_AUTOALLOW":              {"Which tools of the MCP server Claude Code may use without asking: off, read (peers, inbox, topics) or all (also fetch, which writes a file). Default: off. all asks for the name.", "Welche Werkzeuge des MCP-Servers Claude Code ohne Nachfrage nutzen darf: off, read (peers, inbox, topics) oder all (auch fetch, das eine Datei schreibt). Standard: off. all verlangt den Namen."},
		"NATS_MCP_PUSH_FROM":              {"Machines, separated by commas, whose messages are pushed into a Claude Code session that you start yourself. Empty: none.", "Rechner, durch Komma getrennt, deren Nachrichten in eine Claude-Code-Sitzung geschoben werden, die Sie selbst starten. Leer: keiner."},
		"NATS_MCP_TOPICS":                 {"Topics (up to 16, separated by commas) every MCP server subscribes to at its start; unsubscribe refuses them.", "Themen (höchstens 16, durch Komma getrennt), die jeder MCP-Server beim Start abonniert; unsubscribe lehnt sie ab."},
		"NATS_OBJECTS":                    {"true: the group has a store for files (images, PDFs, ZIPs) at its NATS server; needs NATS_MCP=true. It applies when the server of the group is made: later only with a new server (viper down --group, then viper up --group).", "true: die Gruppe hat einen Speicher für Dateien (Bilder, PDFs, ZIPs) an ihrem NATS-Server; braucht NATS_MCP=true. Gilt, wenn der Server der Gruppe angelegt wird: später nur mit einem neuen Server (viper down --group, dann viper up --group)."},
		"NATS_OBJECTS_MAX":                {"Size of the store in MiB (16 to 102400). viper up checks that this plus 1 GiB is free. Default: 256. Applies with a new server of the group.", "Größe des Speichers in MiB (16 bis 102400). viper up prüft, dass dieser Wert plus 1 GiB frei ist. Standard: 256. Gilt mit einem neuen Server der Gruppe."},
		"NATS_OBJECTS_FILE_MAX":           {"Largest file in MiB (1 to 64, at most NATS_OBJECTS_MAX). Default: 8.", "Größte Datei in MiB (1 bis 64, höchstens NATS_OBJECTS_MAX). Standard: 8."},
		"NATS_OBJECTS_TTL":                {"How long a file stays, in days (1 to 365). Default: 7.", "Wie lange eine Datei bleibt, in Tagen (1 bis 365). Standard: 7."},
		"VIPER_HOMEBREW":                  {"1: install Homebrew (brew) on the server; 0 saves 1 to 2 minutes per new server. Default: 1.", "1: Homebrew (brew) auf dem Server installieren; 0 spart 1 bis 2 Minuten je neuem Server. Standard: 1."},
		"VIPER_BREWFILE":                  {"1: apply a Brewfile of the cloned repository with brew bundle. A Brewfile is Ruby: only for repositories you trust. Default: 0.", "1: eine Brewfile des geklonten Repositorys mit brew bundle anwenden. Eine Brewfile ist Ruby: nur für Repositories, denen Sie vertrauen. Standard: 0."},
		"VIPER_BREW_TAPS":                 {"Homebrew taps (owner/repo or owner/repo=URL), separated by spaces. No credentials in a URL.", "Homebrew-Taps (owner/repo oder owner/repo=URL), mit Leerzeichen getrennt. Keine Zugangsdaten in einer URL."},
		"VIPER_BREW_TRUST":                {"Entries for brew trust: owner/repo (a tap), owner/repo/name (a formula), cask:… or command:…, separated by spaces.", "Einträge für brew trust: owner/repo (ein Tap), owner/repo/name (eine Formel), cask:… oder command:…, mit Leerzeichen getrennt."},
		"VIPER_BREW_PACKAGES":             {"Formulae to install (name or owner/repo/name), separated by spaces.", "Zu installierende Formeln (name oder owner/repo/name), mit Leerzeichen getrennt."},
		"VIPER_CODE_SERVER":               {"1: install code-server (VS Code in the browser). Default: 0.", "1: code-server (VS Code im Browser) installieren. Standard: 0."},
		"VIPER_SWAP":                      {"Swap file on the server: 0 (off), a factor of the RAM from 0.1 to 4 (1 = as much as RAM) or a size (4G, 512M). Default: 0.", "Swap-Datei auf dem Server: 0 (aus), ein Faktor vom RAM von 0,1 bis 4 (1 = so viel wie RAM) oder eine Größe (4G, 512M). Standard: 0."},
		"VIPER_CLAUDE_MODEL":              {"Name of the model for the provider of Claude Code that you chose. Default: empty.", "Modellname bei dem Anbieter von Claude Code, den Sie gewählt haben. Standard: leer."},
		"VIPER_CLAUDE_MAX_CONTEXT_TOKENS": {"Context window that Claude Code assumes for the model, in tokens. Default: 200000.", "Kontextfenster, das Claude Code für das Modell annimmt, in Tokens. Standard: 200000."},
	}
}
